#define task_info_init_buffer(buffer, size) \
  do                                        \
    {                                       \
      if (buffer == NULL)                   \
        {                                   \
          buffer = lib_zalloc(size);        \
        }                                   \
    }                                       \
  while (0)

#define task_info_uninit_buffer(buffer) \
  do                                    \
    {                                   \
      if (buffer != NULL)               \
        {                               \
          lib_free(buffer);             \
          buffer = NULL;                \
        }                               \
    }                                   \
  while (0)

