{
  up_systempoweroff();
  return 0;
}
#endif

#ifdef CONFIG_BOARDCTL_RESET
int board_reset(int status)
{
#ifndef CONFIG_ARCH_ARMV8R
  up_systemreset();
#endif
  return 0;
}
#endif

