  struct mod_loadinfo_s loadinfo;

  binfo("board_boot_image %s hdr_size %" PRIu32 "\n", path, hdr_size);

  /* Initialize the ELF library to load the program binary. */

  ret = libelf_initialize(path, &loadinfo);
  if (ret < 0)
    {
      berr("Failed to libelf_initialize: %d\n", ret);
      return ret;
    }

  /* Load the program binary */

  ret = libelf_load_vma(&loadinfo, true);
  if (ret < 0)
    {
      berr("Failed to libelf_load_vma: %d\n", ret);
      return ret;
    }

  /* Reset busy wait status */

#ifdef CONFIG_ARM_BUSY_WAIT
  *g_smp_busy_wait = 0;
#endif
  UP_DSB();

