int main(int argc, FAR char *argv[])
{
  FAR char               *buffer;
  int                     len;
  int                     x;
  int                     running;
  char                    *cmd;
  char                    *arg;
  FAR struct nxplayer_s   *pplayer;

  printf("NxPlayer version " NXPLAYER_VER "\n");
  printf("h for commands, q to exit\n");
  printf("\n");

  /* Initialize our NxPlayer context */

  pplayer = nxplayer_create();
  if (pplayer == NULL)
    {
      printf("Error:  Out of RAM\n");
      return -ENOMEM;
    }

  buffer = lib_get_tempbuffer(LINE_MAX);
  if (buffer == NULL)
    {
      nxplayer_release(pplayer);
      printf("Error: lib_get_tempbuffer failed\n");
      return -ENOMEM;
    }

  /* Loop until the user exits */

  running = TRUE;
  while (running)
    {
      /* Print a prompt */

      printf("nxplayer> ");
      fflush(stdout);

      /* Read a line from the terminal */

      len = readline_stream(buffer, LINE_MAX,
                            stdin, stdout);
      if (len > 0)
        {
          buffer[len] = '\0';
          if (strncmp(buffer, "!", 1) != 0)
            {
              /* nxplayer command */

              if (buffer[len - 1] == '\n')
                {
                  buffer[len - 1] = '\0';
                }

              /* Parse the command from the argument */

              cmd = strtok_r(buffer, " \n", &arg);
              if (cmd == NULL)
